package polymorphism.assigment_problems;

import java.util.*;public class FestivalBonusCalculator {interface Bonus{double amount(double salary);}static class FullTime implements Bonus{public double amount(double s){return s*.10;}}static class PartTime implements Bonus{public double amount(double s){return s*.10;}}static class Intern implements Bonus{public double amount(double s){return 2000;}}public static void main(String[] z){Scanner s=new Scanner(System.in);int n=s.nextInt();double total=0;for(int i=0;i<n;i++){String t=s.next(),name=s.next();double sal=s.nextDouble();Bonus b=t.equals("FULLTIME")?new FullTime():t.equals("PARTTIME")?new PartTime():new Intern();double v=b.amount(sal);System.out.printf(Locale.US,"%s: %.2f%n",name,v);total+=v;}System.out.printf(Locale.US,"Total Bonus: %.2f%n",total);}}
